package com.aistock.scheduler.task;
import com.aistock.scheduler.SchedulerApplication;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.ApplicationContext;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") @SpringBootTest(classes=SchedulerApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE,properties={"spring.cloud.nacos.discovery.enabled=false","spring.cloud.nacos.config.enabled=false","aistock.scheduler.worker-enabled=false","aistock.scheduler.plan-enabled=false","aistock.scheduler.verification-plan-enabled=false"})
class SchedulerWiringTest {
 @DynamicPropertySource static void db(DynamicPropertyRegistry r){String url=System.getenv("SCHEDULER_TEST_DB_URL"),password=System.getenv("SCHEDULER_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_scheduler_test?serverTimezone=UTC".equals(url)||password==null||password.isBlank())throw new IllegalStateException("Only isolated scheduler test DB allowed");r.add("spring.datasource.url",()->url);r.add("spring.datasource.username",()->"root");r.add("spring.datasource.password",()->password);}
 @Autowired ApplicationContext context;
 @Test void fullSchedulerBeansWireWithPlansDisabled(){assertNotNull(context.getBean(com.aistock.scheduler.alert.AlertScanPlan.class));assertNotNull(context.getBean(com.aistock.scheduler.alert.AlertScanRepository.class));assertTrue(context.getBean(com.aistock.scheduler.alert.AlertMarketClient.class) instanceof com.aistock.scheduler.alert.HttpAlertMarketClient);assertNotNull(context.getBean(VerificationScanRepository.class));assertNotNull(context.getBean(DailyVerificationPlan.class));assertNotNull(context.getBean(TaskWorker.class));assertNotNull(context.getBean(RevisionScanRepository.class));assertNotNull(context.getBean(RevisionVerificationPlan.class));assertTrue(context.getBean(RevisionClient.class) instanceof HttpRevisionClient);assertTrue(context.getBean(PredictionTaskClient.class) instanceof HttpPredictionTaskClient);}
}
